<?php defined('BASEPATH') OR exit('No direct script access allowed');class Crm_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function list_resource($type,$org,$filters=array()){$table='crm_'.$type;$this->db->where('organization_id',$org);foreach($filters as $k=>$v)if($v)$this->db->where($k,$v);$order=$type==='activities'?'created_at':'updated_at';return array_map(function($r)use($type){return $this->view($type,$r);},$this->db->order_by($order,'DESC')->get($table)->result_array());}function one($type,$id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('crm_'.$type)->row_array();return $r?$this->view($type,$r):NULL;}function save($type,$id,$org,$uid,$d){$table='crm_'.$type;$now=date('Y-m-d H:i:s');$maps=array('companies'=>array('name','domain','industry','sizeBand'=>'size_band','website','city','country','tags'),'contacts'=>array('firstName'=>'first_name','lastName'=>'last_name','email','phone','companyId'=>'company_id','title','source','status','tags','ownerId'=>'owner_id','notes'),'deals'=>array('name','companyId'=>'company_id','contactId'=>'contact_id','amountCents'=>'amount_cents','currency','stage','probabilityPct'=>'probability_pct','expectedCloseAt'=>'expected_close_at','tags','ownerId'=>'owner_id'),'activities'=>array('kind','subject','body','contactId'=>'contact_id','dealId'=>'deal_id','companyId'=>'company_id','dueAt'=>'due_at','completedAt'=>'completed_at'));$set=array();foreach($maps[$type] as $i=>$o){if(is_int($i))$i=$o;if(array_key_exists($i,$d))$set[$o]=in_array($i,array('tags'),TRUE)?json_encode($d[$i]):(substr($i,-2)==='At'&&$d[$i]?date('Y-m-d H:i:s',strtotime($d[$i])):$d[$i]);}if(!$id){$id=$this->uuid();$set['id']=$id;$set['organization_id']=$org;$set['created_at']=$now;if($type!=='activities')$set['updated_at']=$now;else$set['created_by']=$uid;if($type==='contacts'){$set+=array('source'=>'other','status'=>'lead','tags'=>'[]');}if($type==='companies')$set+=array('size_band'=>'unknown','tags'=>'[]');if($type==='deals'){$prob=array('lead'=>10,'qualified'=>30,'proposal'=>50,'negotiation'=>70,'closed_won'=>100,'closed_lost'=>0);$set+=array('stage'=>'lead','currency'=>'USD','tags'=>'[]');$set['probability_pct']=$set['probability_pct']??$prob[$set['stage']];}$this->db->insert($table,$set);}else{$set['updated_at']=$now;if($type==='deals'&&isset($set['stage'])){$set['stage_changed_at']=$now;if($set['stage']==='closed_won')$set['won_at']=$now;if($set['stage']==='closed_lost')$set['lost_at']=$now;}$this->db->where(array('id'=>$id,'organization_id'=>$org))->update($table,$set);if(!$this->db->affected_rows()&&!$this->one($type,$id,$org))return NULL;}return $this->one($type,$id,$org);}function remove($type,$id,$org){$this->db->where(array('id'=>$id,'organization_id'=>$org))->delete('crm_'.$type);return $this->db->affected_rows()>0;}function stages(){return array(array('key'=>'lead','label'=>'Lead','order'=>0,'probabilityPct'=>10),array('key'=>'qualified','label'=>'Qualified','order'=>1,'probabilityPct'=>30),array('key'=>'proposal','label'=>'Proposal','order'=>2,'probabilityPct'=>50),array('key'=>'negotiation','label'=>'Negotiation','order'=>3,'probabilityPct'=>70),array('key'=>'closed_won','label'=>'Closed Won','order'=>4,'probabilityPct'=>100),array('key'=>'closed_lost','label'=>'Closed Lost','order'=>5,'probabilityPct'=>0));}function rollup($org){$deals=$this->db->where('organization_id',$org)->get('crm_deals')->result_array();$pipe=array();$forecast=$open=$won=0;foreach($this->stages() as $s){$n=0;$sum=0;foreach($deals as $d)if($d['stage']===$s['key']){$n++;$sum+=(int)$d['amount_cents'];}$pipe[]=array('stageKey'=>$s['key'],'label'=>$s['label'],'order'=>$s['order'],'count'=>$n,'sumCents'=>$sum);if(!in_array($s['key'],array('closed_won','closed_lost'))){$open+=$sum;$forecast+=(int)floor($sum*$s['probabilityPct']/100);}if($s['key']==='closed_won')$won=$sum;}$cw=$this->db->where(array('organization_id'=>$org,'stage'=>'closed_won'))->count_all_results('crm_deals');$cl=$this->db->where(array('organization_id'=>$org,'stage'=>'closed_lost'))->count_all_results('crm_deals');return array('counts'=>array('contacts'=>$this->db->where('organization_id',$org)->count_all_results('crm_contacts'),'companies'=>$this->db->where('organization_id',$org)->count_all_results('crm_companies'),'openDeals'=>count($deals)-$cw-$cl,'closedWonDeals'=>$cw,'closedLostDeals'=>$cl,'activities'=>$this->db->where('organization_id',$org)->count_all_results('crm_activities')),'pipeline'=>$pipe,'forecastCents'=>$forecast,'openPipelineCents'=>$open,'closedWonCents'=>$won,'conversionRate'=>$cw+$cl?$cw/($cw+$cl):NULL,'topDeals'=>array(),'recentActivities'=>$this->list_resource('activities',$org),'lastUpdatedAt'=>date('c'));}function view($type,$r){$out=array();foreach($r as $k=>$v){$parts=explode('_',$k);$key=array_shift($parts);foreach($parts as $x)$key.=ucfirst($x);$out[$key]=in_array($k,array('tags'),TRUE)?(json_decode($v,TRUE)?:array()):$v;}unset($out['organizationId']);$out['organizationId']=$r['organization_id'];return $out;}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
